    el('temper-line').textContent = state.temperLine || '';
    el('wick-ai-panel').classList.toggle('thinking', state.turn === 'ai' && state.phase === 'table');
  }

  function renderHands(state) {
    var you = '';
    for (var i = 0; i < state.hands.you.length; i++) {
