/* 1280x720 stage, felt table, lanes, HUD grid and vignette for Cinderwick. */
.stage {
  width: 1280px;
  height: 720px;
  position: relative;
  overflow: hidden;
  background:
    radial-gradient(900px 500px at 18% 0%, rgba(232, 178, 90, 0.16), transparent 60%),
    radial-gradient(700px 500px at 85% 110%, rgba(80, 120, 90, 0.12), transparent 60%),
    linear-gradient(180deg, #1a2420 0%, #12181a 55%, #0e1214 100%);
  color: #efe3c8;
  font-family: Georgia, 'Times New Roman', serif;
  transform-origin: top left;
}
.stage::after {
  content: '';
  position: absolute;
  inset: 0;
  pointer-events: none;
  background: radial-gradient(120% 90% at 50% 45%, transparent 55%, rgba(0, 0, 0, 0.55) 100%);
}
.stage::before {
  content: '';
  position: absolute;
  inset: 0;
  pointer-events: none;
  opacity: 0.35;
  background:
    repeating-linear-gradient(90deg, transparent 0 46px, rgba(0, 0, 0, 0.14) 46px 48px),
    linear-gradient(180deg, rgba(120, 70, 30, 0.25), transparent 90px, transparent calc(100% - 90px), rgba(120, 70, 30, 0.25));
